import { createSlice, PayloadAction, createAsyncThunk } from '@reduxjs/toolkit';
import type { DailyIncidentReport, DailyIncidentReportFilters, DailyIncidentReportStats } from '../../models/DailyIncidentReport';
import { dailyIncidentReportEndpoint } from '../../services/dailyIncidentReports';

// ─────────────────────────────────────────────────────────────────────────────
// State
// ─────────────────────────────────────────────────────────────────────────────

interface DailyIncidentReportsState {
  items:        DailyIncidentReport[];
  filters:      DailyIncidentReportFilters;
  loading:      boolean;
  saving:       boolean;
  statsLoading: boolean;
  stats:        DailyIncidentReportStats;
  error:        string | null;
  pagination: {
    page:       number;
    pageSize:   number;
    totalCount: number;
  };
}

const initialState: DailyIncidentReportsState = {
  items:        [],
  filters:      {},
  loading:      false,
  saving:       false,
  statsLoading: false,
  stats:        { total: 0, withIncident: 0, withoutIncident: 0 },
  error:        null,
  pagination:   { page: 1, pageSize: 20, totalCount: 0 },
};

// ─────────────────────────────────────────────────────────────────────────────
// Thunks
// ─────────────────────────────────────────────────────────────────────────────

export const fetchDailyIncidentReports = createAsyncThunk(
  'dailyIncidentReports/fetchList',
  async (_, thunkAPI) => {
    const state = thunkAPI.getState() as { dailyIncidentReports: DailyIncidentReportsState };
    const { filters, pagination } = state.dailyIncidentReports;
    return dailyIncidentReportEndpoint.getList(filters, pagination.page, pagination.pageSize);
  },
);

export const createDailyIncidentReport = createAsyncThunk(
  'dailyIncidentReports/create',
  async (
    data: Omit<DailyIncidentReport, 'id' | 'idCode' | 'createdById' | 'createdByName' | 'createdAt' | 'updatedAt'>,
  ) => dailyIncidentReportEndpoint.create(data),
);

export const fetchDailyIncidentReportStats = createAsyncThunk(
  'dailyIncidentReports/fetchStats',
  async (_, thunkAPI) => {
    const state = thunkAPI.getState() as { dailyIncidentReports: DailyIncidentReportsState };
    // Stats are not filtered by hasIncident — always pass base filters only
    const { filters } = state.dailyIncidentReports;
    const baseFilters: DailyIncidentReportFilters = {
      fromDate:     filters.fromDate,
      toDate:       filters.toDate,
      departmentId: filters.departmentId,
    };
    return dailyIncidentReportEndpoint.getStats(baseFilters);
  },
);

// ─────────────────────────────────────────────────────────────────────────────
// Slice
// ─────────────────────────────────────────────────────────────────────────────

const dailyIncidentReportsSlice = createSlice({
  name: 'dailyIncidentReports',
  initialState,
  reducers: {
    setFilters(state, action: PayloadAction<DailyIncidentReportFilters>) {
      state.filters         = action.payload;
      state.pagination.page = 1;
    },
    setPage(state, action: PayloadAction<number>) {
      state.pagination.page = action.payload;
    },
  },
  extraReducers: (builder) => {
    builder
      // fetch list
      .addCase(fetchDailyIncidentReports.pending, (state) => {
        state.loading = true;
        state.error   = null;
      })
      .addCase(fetchDailyIncidentReports.fulfilled, (state, action) => {
        state.loading              = false;
        state.items                = action.payload.items;
        state.pagination.totalCount = action.payload.total;
      })
      .addCase(fetchDailyIncidentReports.rejected, (state, action) => {
        state.loading = false;
        state.error   = action.error.message ?? 'Lỗi tải dữ liệu';
      })
      // fetch stats
      .addCase(fetchDailyIncidentReportStats.pending, (state) => {
        state.statsLoading = true;
      })
      .addCase(fetchDailyIncidentReportStats.fulfilled, (state, action) => {
        state.statsLoading = false;
        state.stats        = action.payload;
      })
      .addCase(fetchDailyIncidentReportStats.rejected, (state) => {
        state.statsLoading = false;
      })
      // create
      .addCase(createDailyIncidentReport.pending, (state) => {
        state.saving = true;
        state.error  = null;
      })
      .addCase(createDailyIncidentReport.fulfilled, (state) => {
        state.saving = false;
      })
      .addCase(createDailyIncidentReport.rejected, (state, action) => {
        state.saving = false;
        state.error  = action.error.message ?? 'Lỗi lưu báo cáo';
      });
  },
});

export const { setFilters, setPage } = dailyIncidentReportsSlice.actions;
export default dailyIncidentReportsSlice.reducer;